import { Component, JSX, ParentComponent, Show } from "solid-js";

import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

const FiligreeH1: Component<JSX.HTMLAttributes<HTMLDivElement>> = (props) => {
	return (
		<div
			{...props}
			class={`filigree-divider-h1 ${[props.class ?? ""]}`}
			data-name="Filigree.H1"
		/>
	);
};

const FiligreeH2: Component<JSX.HTMLAttributes<HTMLDivElement>> = (props) => {
	return (
		<div
			{...props}
			class={`filigree-divider-h2 ${[props.class ?? ""]}`}
			data-name="Filigree.H2"
		/>
	);
};

const FiligreeH3: Component<JSX.HTMLAttributes<HTMLDivElement>> = (props) => {
	return (
		<div
			{...props}
			class={`filigree-divider-h3 ${[props.class ?? ""]}`}
			data-name="Filigree.H3"
		/>
	);
};

export interface FiligreeH4Props extends JSX.HTMLAttributes<HTMLDivElement> {
	name?: string;
	filigreeClass?: string;
}

const FiligreeH4: ParentComponent<FiligreeH4Props> = (props) => {
	return (
		<div
			{...props}
			class={`flex flex-row justify-center items-center ${[props.class ?? ""]}`}
			data-name={props.name ?? "Filigree.H4"}
		>
			<div class={`filigree-h4-left ${props.filigreeClass ?? ""}`} />
			{props.children}
			<div class={`filigree-h4-right ${props.filigreeClass ?? ""}`} />
		</div>
	);
};

const FiligreeSmall: Component<JSX.HTMLAttributes<HTMLDivElement>> = (props) => {
	return (
		<div
			{...props}
			class={`filigree-shell-small mt-2\\.5 ${[props.class ?? ""]}`}
			data-name="Filigree.Small"
		/>
	);
};

const FiligreeTitleAccent: ParentComponent<FiligreeH4Props> = (props) => {
	return (
		<div
			{...props}
			class={`flex flex-row justify-center items-center ${[props.class ?? ""]}`}
			data-name={props.name ?? "Filigree.TitleAccent"}
		>
			<div class={`filigree-title-accent-left mr-6 mt-1 ${props.filigreeClass ?? ""}`} />
			{props.children}
			<div class={`filigree-title-accent-right ml-6 mt-1 ${props.filigreeClass ?? ""}`} />
		</div>
	);
};

export interface FiligreeFrameProps {
	hideDecoration?: boolean;
	topClass?: string;
	bottomClass?: string;
}

const FiligreeGoldFrame: ParentComponent<FiligreeFrameProps> = (props) => {
	return (
		<Show
			when={!props.hideDecoration}
			fallback={props.children}
		>
			<div class={`${props.topClass ?? ""} filigree-inner-frame-top-gold`} />
			{props.children}
			<div class={`${props.bottomClass ?? ""} filigree-inner-frame-bottom-gold`} />
		</Show>
	);
};

export interface BaseFiligreeProps {
	topIconClass?: string;
	topIconSrc?: string;
	topIconBackgroundTint?: string;
	topIconTint?: string;
}

const FiligreeTopIcon: Component<BaseFiligreeProps> = (props) => {
	return (
		<>
			<div
				class="w-64 bg-contain bg-no-repeat bg-center -mr-3"
				style={{ "background-image": "url(blp:base_top-filigree_left)" }}
			/>
			<Show
				when={props.topIconSrc !== undefined}
				fallback={
					<div
						class="w-16 bg-contain bg-no-repeat bg-center -mx-6"
						style={{ "background-image": "url(blp:base_top-filigree_center)" }}
					/>
				}
			>
				<div
					class="size-16 bg-contain bg-no-repeat bg-center absolute -top-5"
					style={{
						"background-image": "url(blp:subsystem_panel_header_icon_backing)",
						// eslint-disable-next-line solid/style-prop
						"fxs-background-image-tint": props.topIconBackgroundTint,
					}}
				/>
				<div
					class="size-20 bg-contain bg-no-repeat bg-center absolute flex justify-center items-center -mt-6"
					style={{
						"background-image": "url(blp:pedia_circle_frame)",
					}}
				>
					<div
						class={`${props.topIconClass ?? "size-14"} bg-contain bg-no-repeat bg-center -mt-1`}
						style={{
							"background-image": props.topIconSrc,
							// eslint-disable-next-line solid/style-prop
							"fxs-background-image-tint": props.topIconTint,
						}}
					/>
				</div>
			</Show>
			<div
				class="w-64 bg-contain bg-no-repeat bg-center -ml-3"
				style={{ "background-image": "url(blp:base_top-filigree_right)" }}
			/>
		</>
	);
};

const FiligreeWide: Component = () => {
	return (
		<div
			class="relative"
			style={{
				width: "100%",
				height: "5vh",
				"margin-top": "-0.0vh",
			}}
		>
			<div
				class="absolute bg-contain bg-no-repeat bg-center self-center"
				style={{
					"background-image": "url(blp:popup_paneltop_wide)",
					width: "40%",
					height: "5vh",
				}}
			/>
			<div
				class="absolute bg-no-repeat bg-center -left-2"
				style={{
					"background-image": "url(blp:popup_paneltop_wide)",
					width: "35%",
					height: "5vh",
					"background-position": "left bottom",
					"background-size": "500% 100%",
				}}
			/>
			<div
				class="absolute bg-no-repeat bg-center -right-2"
				style={{
					"background-image": "url(blp:popup_paneltop_wide)",
					width: "35%",
					height: "5vh",
					"background-position": "right bottom",
					"background-size": "500% 100%",
				}}
			/>
		</div>
	);
};

/**
 * A collection of filligree components
 */
export const Filigree = {
	/**
	 * A filigree designed to be used beneath H1 text
	 *
	 * Default implementation: {@link FiligreeH1}
	 */
	H1: ComponentRegistry.register({
		name: "Filigree.H1",
		createInstance: FiligreeH1,
		images: ["blp:header_filigree.png"],
	}),
	/**
	 * A filigree designed to be used beneath H2 text
	 *
	 * Default implementation: {@link FiligreeH2}
	 */
	H2: ComponentRegistry.register({
		name: "Filigree.H2",
		createInstance: FiligreeH2,
		images: ["blp:hud_divider-h2.png"],
	}),
	/**
	 * A filigree designed to be used beneath H3 text
	 *
	 * Default implementation: {@link FiligreeH3}
	 */
	H3: ComponentRegistry.register({
		name: "Filigree.H3",
		createInstance: FiligreeH3,
		images: ["blp:hud_sidepanel_divider.png"],
	}),
	/**
	 * A filigree designed to be used around H4 text
	 *
	 * Default implementation: {@link FiligreeH4}
	 */
	H4: ComponentRegistry.register({
		name: "Filigree.H4",
		createInstance: FiligreeH4,
		images: ["blp:hud_fleur.png"],
	}),
	/**
	 * A filigree designed to be used as a small horizotnal divider
	 *
	 * Default implementation: {@link FiligreeSmall}
	 */
	Small: ComponentRegistry.register({
		name: "Filigree.Small",
		createInstance: FiligreeSmall,
		images: ["blp:shell_small-filigree.png"],
	}),
	/**
	 * A filigree designed to be used around a title text to provide accent either side
	 *
	 * Default implementation: {@link FiligreeTitleAccent}
	 */
	TitleAccent: ComponentRegistry.register({
		name: "Filigree.TitleAccent",
		createInstance: FiligreeTitleAccent,
		images: ["blp:title_accent_filigree"],
	}),
	/**
	/**
	 * A filigree designed to be used as a gold frame around some content
	 *
	 * Default implementation: {@link FiligreeGoldFrame}
	 */
	GoldFrame: ComponentRegistry.register({
		name: "Filigree.GoldFrame",
		createInstance: FiligreeGoldFrame,
		images: ["blp:hud_section-line_gold.png"],
	}),
	/**
	 * A filigree that takes in an icon to display in the middle of itself with css parameters
	 *
	 * Default implementation: {@link FiligreeTopIcon}
	 */
	TopIcon: ComponentRegistry.register({
		name: "Filigree.FiligreeTopIcon",
		createInstance: FiligreeTopIcon,
		images: [
			"blp:base_top-filigree_left",
			"blp:base_top-filigree_center",
			"blp:subsystem_panel_header_icon_backing",
			"blp:pedia_circle_frame",
			"blp:base_top-filigree_right",
		],
	}),

	/**
	 * An extra long filigree for framing the top of a panel
	 *
	 * Default implementation: {@link FiligreeWide}
	 */
	Wide: ComponentRegistry.register({
		name: "Filigree.FiligreeWide",
		createInstance: FiligreeWide,
		images: ["blp:popup_paneltop_wide"],
	}),
};
